/**
 * Generates src/utils/powers/canonical-actives.generated.ts from the only
 * binding Actives rulebook, docs/Rules/Canonical/Actives.md.
 *
 * Usage: node scripts/generate-canonical-actives.mjs [--check]
 *   --check  exit 1 when the generated file is out of date.
 */

import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
export const CANONICAL_ACTIVES_MD = path.join(ROOT, 'docs', 'Rules', 'Canonical', 'Actives.md');
const OUT = path.join(ROOT, 'src', 'utils', 'powers', 'canonical-actives.generated.ts');

function cleanCell(s) {
  return String(s ?? '').replace(/\*\*/g, '').trim();
}

function parseRange(cell) {
  const c = cleanCell(cell);
  if (/^melee reach$/i.test(c)) return { range: 'melee' };
  if (/^self$/i.test(c)) return { range: 'self' };
  const m = c.match(/^(\d+)\s*m$/i);
  if (m) return { rangeM: Number(m[1]) };
  return {};
}

function parseRadius(cell) {
  const m = cleanCell(cell).match(/Radius\s+(\d+)\s*m/i);
  return m ? Number(m[1]) : undefined;
}

function parseSpecials(text) {
  const out = {};
  const re = /\b([A-Z][a-z]+)\((\d+)\)/g;
  let m;
  while ((m = re.exec(text))) {
    const key = m[1].toLowerCase();
    if (!(key in out)) out[key] = Number(m[2]);
  }
  return out;
}

/**
 * Parse every `<h3 id>` Power in Actives.md into a compact PL 1–16 table.
 * @param {string} md
 */
export function parseCanonicalActives(md) {
  const lines = md.replace(/\r\n/g, '\n').split('\n');
  /** @type {Record<string, {title: string, rows: any[]}>} */
  const result = {};
  for (let i = 0; i < lines.length; i++) {
    const h = lines[i].match(/^<h3 id="([^"]+)">\s*(.*)$/);
    if (!h) continue;
    const id = h[1];
    let title = h[2].replace(/<span[\s\S]*$/, '').trim();
    if (!title) title = (lines[i + 1] ?? '').replace(/<span[\s\S]*$/, '').trim();
    let j = i + 1;
    while (j < lines.length && !/^\|\s*\*\*Level\*\*/.test(lines[j]) && !/^<h3 id=/.test(lines[j])) j++;
    if (j >= lines.length || /^<h3 id=/.test(lines[j])) {
      result[id] = { title, rows: [] };
      continue;
    }
    const header = lines[j].split('|').slice(1, -1).map(cleanCell);
    const col = (name) => header.findIndex((x) => x.toLowerCase() === name);
    const iType = col('type');
    const iRange = col('range');
    const iAoe = col('aoe');
    const iEffect = col('effect');
    const iPool = header.findIndex((x) => /recovery pool$/i.test(x));
    const rows = new Array(16).fill(null);
    for (let k = j + 2; k < lines.length && lines[k].startsWith('|'); k++) {
      const cells = lines[k].split('|').slice(1, -1);
      const lvl = Number(cleanCell(cells[0]));
      if (!(lvl >= 1 && lvl <= 16)) continue;
      const type = cleanCell(cells[iType]);
      if (/^unavailable$/i.test(type)) continue;
      const tail = cells.slice(iEffect >= 0 ? iEffect : 1).join(' | ');
      const row = { ...parseRange(cells[iRange]) };
      const radiusM = parseRadius(cells[iAoe]);
      if (radiusM !== undefined) row.radiusM = radiusM;
      const specials = parseSpecials(tail);
      if (Object.keys(specials).length) row.specials = specials;
      const effect = cleanCell(cells[iEffect]);
      const dice = effect.match(/(\d+)d8/);
      if (dice) row.dice = Number(dice[1]);
      const attacks = effect.match(/^(?:Make up to|Autofire)\s+(\d+)\s+(?:melee |ranged )?(?:weapon )?attacks\b/i);
      if (attacks) row.attacks = Number(attacks[1]);
      const hp = effect.match(/^Create a Barrier with (\d+) HP/i);
      if (hp) row.hp = Number(hp[1]);
      const bars = iPool >= 0 ? cleanCell(cells[iPool]).match(/^(?:Restore up to\s+)?(\d+)\s+(?:Scarred\s+)?Bars?\b/i) : null;
      if (bars) row.bars = Number(bars[1]);
      rows[lvl - 1] = row;
    }
    result[id] = { title, rows };
  }
  return result;
}

function render(data) {
  const body = JSON.stringify(data, null, 1)
    .replace(/\n\s*/g, ' ')
    .replace(/\{ "(\w[\w-]*)": \{ "title"/g, '{\n  "$1": { "title"')
    .replace(/\}, "([\w-]+)": \{ "title"/g, '},\n  "$1": { "title"');
  return `// AUTO-GENERATED by scripts/generate-canonical-actives.mjs from
// docs/Rules/Canonical/Actives.md. Do not edit by hand.

export interface CanonicalActiveRow {
  range?: 'melee' | 'self';
  rangeM?: number;
  radiusM?: number;
  specials?: Readonly<Record<string, number>>;
  dice?: number;
  /** Split Attack targets / Autofire attack slots. */
  attacks?: number;
  /** Ranged Barrier HP. */
  hp?: number;
  /** AoE / Single Target Restoration Scarred-Bar pool per Safe Haven Rest. */
  bars?: number;
}

export interface CanonicalActiveTable {
  title: string;
  /** Index 0 = PL 1. \`null\` = Unavailable at that Power Level. */
  rows: readonly (CanonicalActiveRow | null)[];
}

export const CANONICAL_ACTIVES: Readonly<Record<string, CanonicalActiveTable>> = ${body};
`;
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const data = parseCanonicalActives(readFileSync(CANONICAL_ACTIVES_MD, 'utf8'));
  const text = render(data);
  if (process.argv.includes('--check')) {
    const cur = (() => {
      try {
        return readFileSync(OUT, 'utf8');
      } catch {
        return '';
      }
    })();
    if (cur.replace(/\r\n/g, '\n') !== text) {
      console.error('[canonical-actives] generated file is out of date; run node scripts/generate-canonical-actives.mjs');
      process.exit(1);
    }
    console.log('[canonical-actives] up to date');
  } else {
    writeFileSync(OUT, text, 'utf8');
    console.log(`[canonical-actives] ${Object.keys(data).length} Powers → ${path.relative(ROOT, OUT)}`);
  }
}
